const $=s=>document.querySelector(s),KEY='little-hello-friends-v1',DAY=86400000;
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const ordinal=s=>{const [y,m,d]=s.split('-').map(Number);return Date.UTC(y,m-1,d)/DAY};
const ago=n=>{const d=new Date();d.setDate(d.getDate()-n);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
let friends=[],filter='all',editing=null,undo=null,timer;try{friends=JSON.parse(localStorage.getItem(KEY)||'[]').filter(f=>f&&typeof f.name==='string'&&Number.isFinite(f.days)&&f.days>0)}catch{}
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const remaining=f=>f.last?ordinal(f.last)+f.days-ordinal(today()):0;
const rhythm=n=>({7:'Every week',14:'Every 2 weeks',30:'Every month',60:'Every 2 months',90:'Every 3 months',180:'Every 6 months'}[n]||`Every ${n} days`);
const colors=['#e7e9d9','#f1e1d4','#e8e1ed','#dce9e6','#f0e9cf'];
function notify(message,action){clearTimeout(timer);$('#toast').textContent=message;if(action){const b=document.createElement('button');b.textContent='Undo';b.onclick=()=>{action();$('#toast').style.display='none'};$('#toast').append(b)}$('#toast').style.display='block';timer=setTimeout(()=>$('#toast').style.display='none',6500)}
function save(){try{localStorage.setItem(KEY,JSON.stringify(friends))}catch{notify('Your browser couldn’t save these changes. Please free up storage.')}render()}
function render(){const due=friends.filter(f=>remaining(f)<=0).length,soon=friends.filter(f=>remaining(f)>0&&remaining(f)<=7).length;$('#due-count').textContent=due;$('#tab-count').textContent=due;$('#soon-count').textContent=soon;$('#all-count').textContent=friends.length;$('#total-label').textContent=friends.length;document.querySelectorAll('.tabs button').forEach(b=>{b.classList.toggle('active',b.dataset.filter===filter);b.setAttribute('aria-pressed',b.dataset.filter===filter)});const query=$('#search').value.toLowerCase().trim();const shown=friends.filter(f=>(filter==='all'||(filter==='due'?remaining(f)<=0:remaining(f)>0&&remaining(f)<=7))&&f.name.toLowerCase().includes(query)).sort((a,b)=>remaining(a)-remaining(b)||a.name.localeCompare(b.name));
if(!shown.length){$('#list').innerHTML=`<div class="empty"><div class="empty-icon">✳</div><h3>${friends.length?(query?'No friends found':filter==='due'?'A little breathing room.':'Nothing coming up just yet.'):'Every friendship starts with a hello.'}</h3><p>${friends.length?(query?'Try a different name.':'Your circle is here when you’re ready. Check Everyone to see your friends.'):'Add someone you care about and choose a rhythm. We’ll keep your next hello in sight.'}</p>${!friends.length?'<button class="button primary" id="first-add">＋ Add your first friend</button><br><button class="secondary" id="demo">Take a look with example friends</button>':''}</div>`;$('#first-add')?.addEventListener('click',()=>openEditor());$('#demo')?.addEventListener('click',demo);return}
$('#list').innerHTML=shown.map(f=>{const left=remaining(f),elapsed=f.last?ordinal(today())-ordinal(f.last):null,initials=f.name.trim().split(/\s+/).slice(0,2).map(n=>n[0]).join('').toUpperCase();let status=left<0?`${Math.abs(left)}d overdue`:left===0?'Time for a hello':left===1?'Tomorrow':`In ${left} days`;return `<article class="card"><div class="avatar" style="background:${colors[(f.name.charCodeAt(0)||0)%colors.length]}">${escape(initials)}</div><div class="person"><button class="name-button" data-edit="${escape(f.id)}">${escape(f.name)}</button><p>${rhythm(f.days)} <span aria-hidden="true">·</span> ${elapsed===null?'No hello logged yet':elapsed===0?'Connected today':elapsed===1?'Last hello yesterday':`Last hello ${elapsed} days ago`}</p>${f.note?`<p class="note">${escape(f.note)}</p>`:''}</div><div class="status"><span class="badge ${left<=0?'due':''}">${status}</span><small>${left<=0?'A good day to reconnect':'A little hello can wait'}</small></div><button class="contact" data-contact="${escape(f.id)}" aria-label="Mark ${escape(f.name)} as contacted">✓ &nbsp; We connected</button><button class="icon-btn" data-edit="${escape(f.id)}" aria-label="Edit ${escape(f.name)}">⋯</button></article>`}).join('');}
function openEditor(id){editing=id||null;const f=friends.find(f=>f.id===id);$('#modal-title').textContent=f?'Edit friend':'Add a friend';$('#friend-form').reset();$('#name').value=f?.name||'';$('#frequency').value=f?([7,14,30,60,90,180].includes(f.days)?String(f.days):'custom'):'30';$('#custom').value=f?.days||21;$('#custom-label').hidden=$('#frequency').value!=='custom';$('#custom').required=!$('#custom-label').hidden;$('#last').max=today();$('#last').value=f?.last||'';$('#note').value=f?.note||'';$('#delete').hidden=!f;$('#editor').showModal();$('#name').focus()}
$('#add-top').onclick=()=>openEditor();$('#close').onclick=()=>$('#editor').close();$('#frequency').onchange=()=>{$('#custom-label').hidden=$('#frequency').value!=='custom';$('#custom').required=!$('#custom-label').hidden};
$('#friend-form').onsubmit=e=>{e.preventDefault();const name=$('#name').value.trim();if(!name){$('#name').setCustomValidity('Please enter a name.');$('#name').reportValidity();return}const f={id:editing||crypto.randomUUID(),name,days:Number($('#frequency').value==='custom'?$('#custom').value:$('#frequency').value),last:$('#last').value,note:$('#note').value.trim()};const index=friends.findIndex(p=>p.id===editing);if(index<0)friends.push(f);else friends[index]=f;filter='all';$('#search').value='';save();$('#editor').close();notify(index<0?`${name} is in your circle.`:'Friend updated.')};$('#name').oninput=()=>$('#name').setCustomValidity('');
$('#delete').onclick=()=>{const removed=friends.find(f=>f.id===editing);friends=friends.filter(f=>f.id!==editing);save();$('#editor').close();notify(`${removed.name} removed.`,()=>{friends.push(removed);save()})};
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()});$('#search').oninput=render;
$('#list').onclick=e=>{const edit=e.target.closest('[data-edit]'),contact=e.target.closest('[data-contact]');if(edit)openEditor(edit.dataset.edit);if(contact){const f=friends.find(f=>f.id===contact.dataset.contact),last=f.last;f.last=today();save();notify(`A little closer to ${f.name}.`,()=>{const current=friends.find(p=>p.id===f.id);if(current){current.last=last;save()}})}};
function demo(){friends=[{name:'Sophie Chen',days:7,last:ago(10),note:'Ask how the pottery class went'},{name:'James Miller',days:30,last:ago(30),note:''},{name:'Amelia Rose',days:14,last:ago(11),note:'A coffee and a proper catch-up'},{name:'Oliver Park',days:60,last:ago(42),note:''}].map(f=>({...f,id:crypto.randomUUID()}));save();notify('Example friends added. You can edit or remove them.')}
window.addEventListener('storage',e=>{if(e.key===KEY){try{friends=JSON.parse(e.newValue||'[]');render()}catch{}}});window.addEventListener('focus',render);setInterval(render,60000);render();
